import{_ as a,C as n,c as s,o as i,a3 as t,G as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Configure a product","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/basic-setup/configure-product.md","filePath":"master/supply-chain/manufacturing/basic-setup/configure-product.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/manufacturing/basic-setup/configure-product.md"};function c(u,e,d,h,p,g){const o=n("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="configure-a-product" tabindex="-1">Configure a product <a class="header-anchor" href="#configure-a-product" aria-label="Permalink to &quot;Configure a product&quot;">​</a></h1><p>Every manufacturing order makes one product from several components. The finished item and each component are ordinary products. This page shows what a product needs so it can be built, consumed and tracked.</p><blockquote><p><strong>In simple words:</strong> Use a goods product, turn on stock tracking, then attach a recipe in the <strong>Bills of Materials</strong> tab.</p></blockquote><p>Open products from <code>Manufacturing → Products → Products</code>. This is the same product form as in Inventory.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>A product can only be built or consumed when <strong>Type</strong> is <strong>Goods</strong> and <strong>Track Inventory</strong> is on. A service has no stock. Choosing <strong>Track By</strong> needs <code>Inventory → Settings → Manage Traceability → Lots &amp; Serial Numbers</code> to be on. See <a href="./../../inventories/get-started/inventory-settings.html">Inventory settings</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows every product with its price and stock. Use it to find finished goods and components.</p>',8)),r(o,{src:"/images1/manufacturing/prod_list.png",alt:"Manufacturing Products list showing Business Laptop and its components with On Hand values"}),e[1]||(e[1]=t('<h2 id="create-the-finished-product" tabindex="-1">Create the finished product <a class="header-anchor" href="#create-the-finished-product" aria-label="Permalink to &quot;Create the finished product&quot;">​</a></h2><ol><li>Go to <code>Manufacturing → Products → Products</code> and click <strong>New Product</strong>.</li><li>Enter the <strong>Name</strong> <strong>Business Laptop</strong>.</li><li>Set <strong>Type</strong> to <strong>Goods</strong>.</li><li>Fill <strong>Price</strong> and <strong>Cost</strong>.</li><li>In the <strong>Inventory</strong> section turn on <strong>Track Inventory</strong>.</li><li>Click <strong>Create</strong>.</li></ol>',2)),r(o,{src:"/images1/manufacturing/prod_create_finished.png",alt:"New product form for Business Laptop with Type Goods, Price, Cost and Track Inventory on"}),e[2]||(e[2]=t('<h3 id="fields-that-matter-for-manufacturing" tabindex="-1">Fields that matter for manufacturing <a class="header-anchor" href="#fields-that-matter-for-manufacturing" aria-label="Permalink to &quot;Fields that matter for manufacturing&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The name shown on orders and work orders.</li><li><strong><em>Type:</em></strong> Choose <strong>Goods</strong>. Manufacturing needs stock.</li><li><strong><em>Track Inventory:</em></strong> Turn on so Aureus counts the stock of components and finished goods.</li><li><strong><em>Track By:</em></strong> <strong>By Quantity</strong>, <strong>By Lots</strong> or <strong>By Unique Serial Number</strong>. Use lots or serial numbers when you must trace each batch or unit.</li><li><strong><em>Unit of Measure:</em></strong> The unit used on the recipe and the order, such as Units.</li><li><strong><em>Cost:</em></strong> Used to work out the cost of components and the finished unit. See <a href="./manufacturing-order-costs.html">Manufacturing order costs</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Choose <strong>Track By</strong> before the first stock arrives. Changing it later can leave old quantities without a lot or serial number. See <a href="./../workflows/lots-and-serial-numbers.html">Lots and serial numbers</a>.</p></div><h2 id="create-the-components" tabindex="-1">Create the components <a class="header-anchor" href="#create-the-components" aria-label="Permalink to &quot;Create the components&quot;">​</a></h2><p>Create each component the same way. For the Business Laptop these are Motherboard, RAM 16GB, SSD 512GB, Laptop Battery, LCD Screen 14-inch and Laptop Chassis. Load opening stock with <strong>Update Quantity</strong> or a receipt. See <a href="./../../inventories/products/configure-product.html">Configure a product for inventory</a>.</p><h2 id="the-bills-of-materials-tab" tabindex="-1">The Bills of Materials tab <a class="header-anchor" href="#the-bills-of-materials-tab" aria-label="Permalink to &quot;The Bills of Materials tab&quot;">​</a></h2><p>Open a saved product. The sub tabs next to <strong>View</strong> and <strong>Edit</strong> include <strong>Bills of Materials</strong>. It lists every recipe that builds this product.</p><ol><li>Open <strong>Business Laptop</strong>.</li><li>Click <strong>Bills of Materials</strong> in the switcher at the top.</li><li>Click <strong>New Bill of Material</strong>. The product is already filled in.</li></ol>',8)),r(o,{src:"/images1/manufacturing/prod_bom_tab.png",alt:"Business Laptop product page, Bills of Materials tab listing BOM-MC-LAPTOP"}),e[3]||(e[3]=t('<p>See <a href="./bill-of-materials.html">Bill of materials</a> for every field.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Stock lives as a quantity per product and location. A manufacturing order reserves component quantities, then moves them out when you produce. The finished product is added to stock at the end.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./bill-of-materials.html">Bill of materials</a></li><li><a href="./../../inventories/products/configure-product.html">Configure a product for inventory</a></li><li><a href="./../../../sales/sales/products-prices/manage-products.html">Manage products in Sales</a></li><li><a href="./../../inventories/tracking/lots-and-serial-numbers.html">Lots and serial numbers</a></li></ul>',5))])}const b=a(l,[["render",c]]);export{f as __pageData,b as default};
